import { promises as fs } from "node:fs";
import path from "node:path";
import { UPLOAD_DIR } from "@/lib/content";
import { isSupabaseEnabled, readRemoteMedia } from "@/lib/supabase";

const TYPES: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  avif: "image/avif",
};

/** Serves images uploaded from the dashboard (data/uploads locally, the site_media table with Supabase). */
export async function GET(_request: Request, { params }: RouteContext<"/media/[name]">) {
  const { name } = await params;
  // Names are generated by the upload route; anything else is rejected outright.
  const match = /^[a-z0-9]+-[a-f0-9]{12}\.(png|jpg|gif|webp|avif)$/.exec(name);
  if (!match) return new Response("Not found", { status: 404 });

  const headers = {
    "Content-Type": TYPES[match[1]],
    "Cache-Control": "public, max-age=31536000, immutable",
    "X-Content-Type-Options": "nosniff",
  };

  try {
    const data = await fs.readFile(path.join(UPLOAD_DIR, name));
    return new Response(new Uint8Array(data), { headers });
  } catch {
    // Not on disk: fall through to Supabase when it is configured.
  }

  if (isSupabaseEnabled()) {
    const data = await readRemoteMedia(name).catch(() => null);
    if (data) return new Response(data, { headers });
  }
  return new Response("Not found", { status: 404 });
}
